1	'use client';
2	
3	import { useEffect } from 'react';
4	import { useSession, signOut } from 'next-auth/react';
5	import { PasswordSetupForm } from '@nia/prism/core/components/PasswordSetupForm';
6	import { useRouter } from 'next/navigation';
7	import { LoginForm } from '@dashboard/components/login-form';
8	import { ThemeToggle } from '../../../components/theme-toggle';
9	import { useState } from 'react';
10	
11	export default function DashboardLoginPage() {
12	  const { data: session, status } = useSession();
13	  const router = useRouter();
14	  const [isCheckingAccess, setIsCheckingAccess] = useState(false);
15	
16	  useEffect(() => {
17	    if (status === 'authenticated' && !session?.user?.email) {
18	      signOut({ redirect: false });
19	      return;
20	    }
21	
22	    if (status === 'authenticated' && session?.user?.email) {
23	      let cancelled = false;
24	      setIsCheckingAccess(true);
25	      (async () => {
26	        try {
27	          const response = await fetch('/dashboard/api/users/me/tenant-roles', {
28	            credentials: 'include',
29	          });
30	          if (!response.ok) {
31	            throw new Error('Failed to resolve tenant roles');
32	          }
33	          const data = await response.json();
34	          const hasAdminAccess =
35	            data?.roles?.some((role: { role?: string }) => role.role === 'admin' || role.role === 'owner') || false;
36	
37	          if (cancelled) return;
38	          if (hasAdminAccess) {
39	            router.push('/dashboard/assistants');
40	            return;
41	          }
42	
43	          await signOut({ redirect: true, callbackUrl: '/dashboard/login?error=NoAccess' });
44	        } catch {
45	          if (!cancelled) {
46	            await signOut({ redirect: true, callbackUrl: '/dashboard/login?error=NoAccess' });
47	          }
48	        } finally {
49	          if (!cancelled) {
50	            setIsCheckingAccess(false);
51	          }
52	        }
53	      })();
54	
55	      return () => {
56	        cancelled = true;
57	      };
58	    }
59	  }, [session, status, router]);
60	
61	  if (status === 'loading' || isCheckingAccess) {
62	    return (
63	      <div className="flex items-center justify-center min-h-screen">
64	        <div className="text-center">
65	          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary mx-auto"></div>
66	          <p className="mt-2 text-sm text-muted-foreground">Loading...</p>
67	        </div>
68	      </div>
69	    );
70	  }
71	
72	  if (status === 'authenticated' && (session as any)?.user?.mustSetPassword && !(session as any)?.user?.google_access_token) {
73	    return (
74	      <div className="min-h-screen flex flex-col items-center justify-center p-6">
75	        <div className="mb-6 text-center max-w-md">
76	          <h1 className="text-2xl font-semibold mb-2">Set Your Password</h1>
77	          <p className="text-sm text-muted-foreground">Your account was created without a password. Please set one now to complete setup.</p>
78	        </div>
79	        <PasswordSetupForm onSuccess={() => { window.location.href = '/dashboard/assistants'; }} />
80	        <button onClick={() => signOut({ redirect: true })} className="mt-6 text-xs text-muted-foreground underline">Sign out</button>
81	      </div>
82	    );
83	  }
84	
85	  return (
86	    <div className="min-h-screen bg-background dark:bg-slate-900 text-foreground relative overflow-hidden">
87	      <div className='fixed top-10 left-12 z-50'>
88	        <img
89	          src="/Nia Logo 1.svg"
90	          alt="Nia Logo"
91	          className="w-16 h-16"
92	        />
93	      </div>
94	
95	      <div className='fixed top-6 right-6 z-50'>
96	        <ThemeToggle />
97	      </div>
98	
99	      <div className="flex h-screen w-full">
100	        <div className="flex-1 flex items-center justify-start pl-12 pr-8">
