1	/**
2	 * PearlOS QA Screenshot Script
3	 *
4	 * Authenticates against the Interface app, waits for the ActiveJobsWidget,
5	 * captures a timestamped screenshot of the widget, and saves it to
6	 * /qa/screenshots/.
7	 *
8	 * Environment variables (read from .env.local by default):
9	 *   DASHBOARD_ADMIN_EMAIL    - login email
10	 *   DASHBOARD_ADMIN_PASSWORD - login password
11	 *   PEARLOS_URL              - base URL (default: http://localhost:3000)
12	 *
13	 * Usage:
14	 *   npx playwright test --config scripts/qa-screenshot.config.ts
15	 *   # or via npm script:
16	 *   npm run qa:screenshot
17	 */
18	
19	import { chromium, type Page } from 'playwright';
20	import * as fs from 'fs';
21	import * as path from 'path';
22	import * as dotenv from 'dotenv';
23	
24	// Load env
25	dotenv.config({ path: path.resolve(__dirname, '..', '.env.local') });
26	
27	const BASE_URL = process.env.PEARLOS_URL || 'http://localhost:3000';
28	const EMAIL = process.env.DASHBOARD_ADMIN_EMAIL;
29	const PASSWORD = process.env.DASHBOARD_ADMIN_PASSWORD;
30	const SCREENSHOTS_DIR = path.resolve(__dirname, '..', 'qa', 'screenshots');
31	
32	async function authenticate(page: Page): Promise<void> {
33	  if (!EMAIL || !PASSWORD) {
34	    throw new Error(
35	      'Missing DASHBOARD_ADMIN_EMAIL or DASHBOARD_ADMIN_PASSWORD in environment',
36	    );
37	  }
38	
39	  await page.goto(`${BASE_URL}/login`, { waitUntil: 'networkidle', timeout: 30_000 });
40	
41	  // Fill login form
42	  await page.fill('#email-input', EMAIL);
43	  await page.fill('#password-input', PASSWORD);
44	
45	  // Submit — find the submit button within the login form
46	  await page.click('form button[type="submit"], form .login-button, form button');
47	
48	  // Wait for navigation away from /login
49	  await page.waitForURL((url) => !url.pathname.includes('/login'), {
50	    timeout: 30_000,
51	  });
52	
53	  // Extra settle time for React hydration
54	  await page.waitForTimeout(3000);
55	}
56	
57	async function waitForActiveJobsWidget(page: Page): Promise<void> {
58	  // The ActiveJobsWidget doesn't have a data-testid, so we look for its
59	  // characteristic class or the component's wrapper. The widget uses the
60	  // Gohufont font-face with id='gohufont-active-jobs' as a fingerprint.
61	  // We wait for either the style tag (proving the component mounted) or
62	  // fall back to a generous timeout.
63	  try {
64	    await page.waitForFunction(
65	      () => !!document.getElementById('gohufont-active-jobs'),
66	      { timeout: 20_000 },
67	    );
68	  } catch {
69	    console.warn(
70	      'ActiveJobsWidget font-face tag not found — widget may not be rendered. Continuing anyway.',
71	    );
72	  }
73	
74	  // Let animations settle
75	  await page.waitForTimeout(2000);
76	}
77	
78	function screenshotFilename(label: string): string {
79	  const ts = new Date().toISOString().replace(/[:.]/g, '-');
80	  const slug = label.replace(/[^a-z0-9]+/gi, '-').toLowerCase();
81	  return `${slug}-${ts}.png`;
82	}
83	
84	async function main() {
85	  fs.mkdirSync(SCREENSHOTS_DIR, { recursive: true });
86	
87	  const browser = await chromium.launch({ headless: true });
88	  const context = await browser.newContext({
89	    viewport: { width: 1280, height: 800 },
90	  });
